// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockTime) public {
        amount = bound(amount, 10 ether, 10 ether);
        blockTime = bound(blockTime, 1, type(uint256).max - 1);
        vm.assume(blockTime > c.pastBlockTime());

        vm.warp(blockTime);

        (bool success, ) = address(c).call{value: amount}("");

        assertTrue(success && c.pastBlockTime() > blockTime);
    }
}

